class Surf < Formula
  desc "Headless browser engine CLI: fetch, serve CDP, extract design, speak MCP"
  homepage "https://github.com/qzmfranklin/homebrew-tap"
  # Platform choice lives in the argument, not in an on_macos block:
  # brew does not allow `url`/`sha256` inside an on_system block.
  # macOS is one universal (arm64 + x86_64) binary, so it needs no arch split.
  url on_system_conditional(
    macos: "https://github.com/qzmfranklin/homebrew-tap/releases/download/surf-0.2.7/surf-0.2.7-darwin-universal.xz",
    linux: on_arch_conditional(
      intel: "https://github.com/qzmfranklin/homebrew-tap/releases/download/surf-0.2.7/surf-0.2.7-linux-amd64.xz",
    ),
  )
  version "0.2.7"
  sha256 on_system_conditional(
    macos: "561035188498cf0681dbcc1320b82798fa95af50eef5fb1eb66ee828c3b4cec0",
    linux: on_arch_conditional(
      intel: "9bfe81c70bc56bd316706e77d12eedfa7d85d7b80c3be2e9474028fc6bd1f8cf",
    ),
  )
  license :cannot_represent

  def install
    # The asset is the BINARY ITSELF, xz'd by brew_artifact (the single-file
    # form, rules_brew plan 0006: a lone binary ships as bare .xz, never a tar
    # containing one file — the retired package.sh channel's tarball members
    # were exactly {surf}, so the CONTENT is unchanged; only the NAME is the
    # generated surf-{version}-{os}-{arch}.xz). Homebrew stages a bare .xz
    # download DECOMPRESSED under the ASSET name — the version-suffixed
    # surf-{version}-{os}-{arch}, not `surf` — so glob it and install under the
    # canonical command name.
    bin.install Dir["surf-*"].first => "surf"
    # A bare .xz carries no mode bits: the decompressed binary lands 0644 and
    # every later step that execs it gets EACCES (the yag 0.18.0 linux tap
    # install failed exactly here). macOS re-chmods inside its ad-hoc
    # codesign stanza (generated by the recipe, replacing the hand-rolled
    # stanza surf.rb used to carry); linux needs it here.
    chmod 0755, bin/"surf"

    # Ad-hoc codesign on macOS. This is INTENTIONAL and load-bearing, not a
    # workaround: the binary is unsigned, and macOS refuses to exec an unsigned
    # or stale-signed Mach-O. Writing the file also invalidates any prior
    # signature, so it must be re-signed after install.
    #
    # chmod first: Homebrew stages files read-only, and both xattr and codesign
    # need to WRITE to the binary (xattr fails with EACCES otherwise).
    if OS.mac?
      chmod 0755, bin/"surf"
      system "/usr/bin/xattr", "-cr", bin/"surf"
      system "/usr/bin/codesign", "--force", "--sign", "-", bin/"surf"
    end
  end

  def post_install
    linked = HOMEBREW_PREFIX/"bin/surf"
    if linked.exist? && !linked.symlink?
      opoo <<~EOS
        Replacing a non-Homebrew surf at #{linked}.
        That file was almost certainly left by the legacy install script.
        The Homebrew-managed surf is now the one on your PATH.
      EOS
      linked.unlink
    end

    # Idempotent, and also repairs the case where the legacy binary was
    # deleted by hand: brew never created the symlink, so the tool was
    # missing from PATH entirely.
    linked.make_relative_symlink(bin/"surf") unless linked.symlink?
  end


  def caveats
    on_linux do
      <<~EOS
        surf's linux binary is glibc-dynamic: it links the system libc (libc.so.6,
        libm.so.6, libgcc_s.so.1) and runs on ubuntu22 and newer (glibc >= 2.35) —
        the Ubuntu-22.04-sysroot cross toolchain's floor. surf's engine embeds a
        prebuilt v8 static archive whose link lane is the glibc one, so the static
        musl shape some sibling formulas carry does not apply to surf.

        On hosts with glibc < 2.39 (Ubuntu 22.04 and older), Homebrew adds gcc and
        glibc as implicit dependencies to EVERY formula and builds them from source.
        This formula carries no real dependencies, so install it there with:

          brew install --ignore-dependencies surf

        On glibc >= 2.39 hosts (Ubuntu 24.04+, Homebrew's own supported set), plain
        `brew install qzmfranklin/tap/surf` works with no extra pulls.
      EOS
    end
  end

  test do
    # The version check is the CLI's own --version (clap prints
    # "surf <SURF_BUILD_VERSION>"; the pin lives in impl/surf/BUILD.bazel,
    # mirrored by publish/pins.bzl's VERSION — the recipe's version stanza and
    # the binary's self-report must agree). The absorbed worker subcommand is
    # not exercised here — its stdin protocol is the stripped-artifact gate's
    # contract (private/cli/stripped in the module), not brew's smoke test.
    assert_match "surf #{version}", shell_output("#{bin}/surf --version")
  end
end
